packaging.tags._py_interpreter_range:
def _py_interpreter_range(py_version: PythonVersion) -> Iterator[str]:
    """
    Yields Python versions in descending order.

    After the latest version, the major-only version will be yielded, and then
    all previous versions of that major version.
    """
    if len(py_version) > 1:
        yield f'py{_version_nodot(py_version[:2])}'
    yield f'py{py_version[0]}'
    if len(py_version) > 1:
        for minor in range(py_version[1] - 1, -1, -1):
            yield f'py{_version_nodot((py_version[0], minor))}'

packaging.tags._mac_binary_formats:
def _mac_binary_formats(version: AppleVersion, cpu_arch: str) -> list[str]:
    formats = [cpu_arch]
    if cpu_arch == 'x86_64':
        if version < (10, 4):
            return []
        formats.extend(['intel', 'fat64', 'fat32'])
    elif cpu_arch == 'i386':
        if version < (10, 4):
            return []
        formats.extend(['intel', 'fat32', 'fat'])
    elif cpu_arch == 'ppc64':
        if (version > (10, 5) or version < (10, 4)):
            return []
        formats.append('fat64')
    elif cpu_arch == 'ppc':
        if version > (10, 6):
            return []
        formats.extend(['fat32', 'fat'])
    if cpu_arch in {'arm64', 'x86_64'}:
        formats.append('universal2')
    if cpu_arch in {'x86_64', 'i386', 'ppc64', 'ppc', 'intel'}:
        formats.append('universal')
    return formats

packaging.tags._mac_arch:
def _mac_arch(arch: str, is_32bit: bool = _32_BIT_INTERPRETER) -> str:
    if not is_32bit:
        return arch
    if arch.startswith('ppc'):
        return 'ppc'
    return 'i386'

packaging._musllinux._get_musl_version:
@functools.lru_cache
def _get_musl_version(executable: str) -> _MuslVersion | None:
    """Detect currently-running musl runtime version.

    This is done by checking the specified executable's dynamic linking
    information, and invoking the loader to parse its output for a version
    string. If the loader is musl, the output would be something like::

        musl libc (x86_64)
        Version 1.2.2
        Dynamic Program Loader
    """
    try:
        with open(executable, 'rb') as f:
            ld = ELFFile(f).interpreter
    except (OSError, TypeError, ValueError):
        return None
    if (ld is None or 'musl' not in ld):
        return None
    proc = subprocess.run([ld], check=False, stderr=subprocess.PIPE, text=True)
    return _parse_musl_version(proc.stderr)

packaging._musllinux._parse_musl_version:
def _parse_musl_version(output: str) -> _MuslVersion | None:
    lines = [n for n in (n.strip() for n in output.splitlines()) if n]
    if (len(lines) < 2 or lines[0][:4] != 'musl'):
        return None
    m = re.match('Version (\\d+)\\.(\\d+)', lines[1])
    if not m:
        return None
    return _MuslVersion(major=int(m.group(1)), minor=int(m.group(2)))

